import json
L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64
s = set(L)
triples = []
for i in range(len(L)):
    a = L[i]
    for j in range(i+1, len(L)):
        b = L[j]
        c = a + b
        if c in s:
            triples.append((a, b, c))

element_to_triples = {x: [] for x in L}
for idx, (a, b, c) in enumerate(triples):
    element_to_triples[a].append(idx)
    element_to_triples[b].append(idx)
    element_to_triples[c].append(idx)

solution = None

def search(remaining, chosen):
    global solution
    if not remaining:
        solution = chosen
        return True
    min_elem = None
    min_opts = None
    for e in remaining:
        opts = [idx for idx in element_to_triples[e] if all(x in remaining for x in triples[idx])]
        if not opts:
            return False
        if min_opts is None or len(opts) < len(min_opts):
            min_opts = opts
            min_elem = e
            if len(min_opts) == 1:
                break
    for idx in min_opts:
        a, b, c = triples[idx]
        new_remaining = remaining - {a, b, c}
        if search(new_remaining, chosen + [(a, b, c)]):
            return True
    return False

search(set(L), [])
if solution is None:
    witness = {'polarity':'negative','evidence':{'path':'execution://witness'},'basis':'search','search_exhausted':True,'method':'backtrack'}
else:
    witness = {'polarity':'positive','evidence':{'path':'execution://witness'},'data':{'triples':solution}}
print('WITNESS: ' + json.dumps(witness))
